import { useState, useEffect } from "react";
import {
  Users,
  CalendarDays,
  Wallet,
  Lock,
  Unlock,
  Plus,
  X,
  LogOut,
  Trash2,
  Pencil,
  Mail,
  MapPin,
  Copy,
  TrendingUp,
  Trophy,
} from "lucide-react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import { supabase } from "./lib/supabaseClient";

const LOGO = "data:image/png;base64,";

const C = {
  bg: "#0A2F24",
  bgElevated: "#0F3B2D",
  bgCard: "#134634",
  line: "rgba(241,250,238,0.14)",
  lineSoft: "rgba(241,250,238,0.07)",
  accent: "#FFC857",
  accent2: "#EF6461",
  text: "#F4F1EA",
  textMuted: "#9FC2AE",
};

const LOCATIONS = ["Waldorf suli", "Vasas Jégpálya"];
const LOCATION_COSTS = { "Waldorf suli": 25000, "Vasas Jégpálya": 10000 };
const ADMIN_EMAIL = "svatsportegyesulet@gmail.com";

const DEFAULT_PLAYERS = [
  { id: "p1", name: "Krausz Tamás", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: true },
  { id: "p2", name: "Farkas Dániel", email: "farkas.dani24@gmail.com", phone: "", photo: "", jerseyNumber: "", isAdmin: true },
  { id: "p3", name: "Molnár Antal", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: false },
  { id: "p4", name: "Széles Tibor", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: false },
  { id: "p5", name: "Kósa Gyula", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: false },
];

function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function nextWednesdayISO() {
  const d = new Date();
  const day = d.getDay();
  const diff = (3 - day + 7) % 7;
  const target = new Date(d);
  target.setDate(d.getDate() + diff);
  return target.toISOString().slice(0, 10);
}

function fmtDate(d) {
  try {
    return new Date(d).toLocaleDateString("hu-HU", { month: "short", day: "numeric", weekday: "short" });
  } catch {
    return d;
  }
}

function fmtHUF(n) {
  return (n || 0).toLocaleString("hu-HU") + " Ft";
}

function isOccasionPast(occasion) {
  if (!occasion) return false;
  const end = new Date(`${occasion.date}T${occasion.endTime || "23:59"}`);
  return new Date() > end;
}

function durationMinutes(o) {
  if (!o.startTime || !o.endTime) return 0;
  const [sh, sm] = o.startTime.split(":").map(Number);
  const [eh, em] = o.endTime.split(":").map(Number);
  let diff = eh * 60 + em - (sh * 60 + sm);
  if (diff < 0) diff += 24 * 60;
  return diff;
}

function buildDebtMessage(debts) {
  if (debts.length === 0) return "Jelenleg mindenki rendezte a tartozását! 🎉";
  const lines = debts.map((p) => `${p.name}: ${fmtHUF(p.debt)}`);
  return ["Tartozás lista - Újpesti Apák SVAT SE", ""].concat(lines).join("\n");
}

function buildDebtMailto(debts, players) {
  const emails = players.map((p) => p.email).filter(Boolean);
  const subject = "Tartozás lista - " + new Date().toLocaleDateString("hu-HU");
  const body = buildDebtMessage(debts);
  return `mailto:?bcc=${encodeURIComponent(emails.join(","))}&subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

function buildMailto(occasion, players) {
  const emails = players.map((p) => p.email).filter(Boolean);
  const locationLabel = occasion.location === "Egyéb" ? occasion.locationOther : occasion.location;
  const subject = occasion.type === "esemeny" ? `Új esemény: ${occasion.title}` : `Heti foci - ${fmtDate(occasion.date)}`;
  const body = [
    "Szia!",
    "",
    `Új ${occasion.type === "esemeny" ? "esemény" : "foci alkalom"} lett kiírva:`,
    `Dátum: ${occasion.date}`,
    `Időpont: ${occasion.startTime || "?"} - ${occasion.endTime || "?"}`,
    `Helyszín: ${locationLabel || "?"}`,
    occasion.type === "foci" ? `Díj: ${fmtHUF(occasion.fee)} (csak ha jössz)` : "",
    "",
    "Üdv,",
    "Újpesti Apák - SVAT SE",
  ].filter(Boolean).join("\n");
  return `mailto:?bcc=${encodeURIComponent(emails.join(","))}&subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

// --- Supabase <-> app adat mapper függvények (snake_case <-> camelCase) ---
function fromDbPlayer(row) {
  return { id: row.id, name: row.name, email: row.email || "", phone: row.phone || "", photo: row.photo || "", jerseyNumber: row.jersey_number || "", isAdmin: !!row.is_admin };
}
function toDbPlayer(p) {
  return { id: p.id, name: p.name, email: p.email || null, phone: p.phone || null, photo: p.photo || null, jersey_number: p.jerseyNumber || null, is_admin: !!p.isAdmin };
}
function fromDbOccasion(row) {
  return { id: row.id, type: row.type, title: row.title, date: row.date, startTime: row.start_time, endTime: row.end_time, location: row.location, locationOther: row.location_other || "", fee: row.fee || 0, cost: row.cost || 0, responses: row.responses || {}, payments: row.payments || {} };
}
function toDbOccasion(o) {
  return { id: o.id, type: o.type, title: o.title, date: o.date, start_time: o.startTime, end_time: o.endTime, location: o.location, location_other: o.locationOther || null, fee: o.fee || 0, cost: o.cost || 0, responses: o.responses || {}, payments: o.payments || {} };
}
function fromDbExtra(row) {
  return { id: row.id, label: row.label, amount: row.amount, targetIds: row.target_ids || [], payments: row.payments || {} };
}
function toDbExtra(f) {
  return { id: f.id, label: f.label, amount: f.amount, target_ids: f.targetIds || [], payments: f.payments || {} };
}

export default function App() {
  const [loading, setLoading] = useState(true);
  const [players, setPlayers] = useState([]);
  const [occasions, setOccasions] = useState([]);
  const [extraFees, setExtraFees] = useState([]);
  const [adminPassword, setAdminPassword] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [storageError, setStorageError] = useState(false);

  const [tab, setTab] = useState("home");
  const [selectedId, setSelectedId] = useState(null);

  const [showAdminModal, setShowAdminModal] = useState(false);
  const [adminInput, setAdminInput] = useState("");
  const [adminError, setAdminError] = useState("");

  const [showPlayerForm, setShowPlayerForm] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState(null);
  const [playerDraft, setPlayerDraft] = useState({ name: "", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: false });

  const [showNewForm, setShowNewForm] = useState(false);
  const [newType, setNewType] = useState("foci");
  const [newTitle, setNewTitle] = useState("");
  const [newDate, setNewDate] = useState(nextWednesdayISO());
  const [newStart, setNewStart] = useState("19:30");
  const [newEnd, setNewEnd] = useState("21:00");
  const [newLocation, setNewLocation] = useState(LOCATIONS[0]);
  const [newLocationOther, setNewLocationOther] = useState("");
  const [newFee, setNewFee] = useState(2000);
  const [newCost, setNewCost] = useState(LOCATION_COSTS[LOCATIONS[0]] || 0);

  const [showExtraForm, setShowExtraForm] = useState(false);
  const [extraDraft, setExtraDraft] = useState({ label: "", amount: "", targetIds: [] });

  useEffect(() => {
    loadAll();
  }, []);

  async function loadAll() {
    setLoading(true);
    try {
      const [pRes, oRes, eRes, sRes] = await Promise.all([
        supabase.from("players").select("*"),
        supabase.from("occasions").select("*"),
        supabase.from("extra_fees").select("*"),
        supabase.from("settings").select("*").eq("key", "admin_password").maybeSingle(),
      ]);

      let playerRows = pRes.data || [];
      if (playerRows.length === 0) {
        await supabase.from("players").insert(DEFAULT_PLAYERS.map(toDbPlayer));
        const refetch = await supabase.from("players").select("*");
        playerRows = refetch.data || [];
      }

      const occ = (oRes.data || []).map(fromDbOccasion).sort((a, b) => new Date(b.date) - new Date(a.date));
      setPlayers(playerRows.map(fromDbPlayer));
      setOccasions(occ);
      setExtraFees((eRes.data || []).map(fromDbExtra));
      setAdminPassword(sRes.data ? sRes.data.value : null);
      setSelectedId(occ[0]?.id ?? null);
    } catch (err) {
      console.error(err);
      setStorageError(true);
    }
    setLoading(false);
  }

  async function persistOccasion(updated) {
    const { error } = await supabase.from("occasions").update(toDbOccasion(updated)).eq("id", updated.id);
    if (error) {
      console.error(error);
      setStorageError(true);
    }
  }

  async function handleAdminSubmit() {
    if (!adminPassword) {
      if (adminInput.trim().length < 4) {
        setAdminError("Legalább 4 karakter legyen");
        return;
      }
      const { error } = await supabase.from("settings").upsert({ key: "admin_password", value: adminInput.trim() });
      if (error) {
        console.error(error);
        setAdminError("A mentés nem sikerült, próbáld újra");
        return;
      }
      setAdminPassword(adminInput.trim());
      setIsAdmin(true);
      setShowAdminModal(false);
      setAdminInput("");
      setAdminError("");
    } else if (adminInput === adminPassword) {
      setIsAdmin(true);
      setShowAdminModal(false);
      setAdminInput("");
      setAdminError("");
    } else {
      setAdminError("Hibás jelszó");
    }
  }

  function openPlayerForm(player) {
    if (player) {
      setEditingPlayer(player);
      setPlayerDraft({ name: player.name, email: player.email || "", phone: player.phone || "", photo: player.photo || "", jerseyNumber: player.jerseyNumber || "", isAdmin: !!player.isAdmin });
    } else {
      setEditingPlayer(null);
      setPlayerDraft({ name: "", email: "", phone: "", photo: "", jerseyNumber: "", isAdmin: false });
    }
    setShowPlayerForm(true);
  }

  async function submitPlayer() {
    if (!playerDraft.name.trim()) return;
    const id = editingPlayer ? editingPlayer.id : uid();
    const row = toDbPlayer({ id, ...playerDraft });
    const { error } = await supabase.from("players").upsert(row);
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setPlayers((prev) => {
      const exists = prev.some((p) => p.id === id);
      return exists ? prev.map((p) => (p.id === id ? { ...playerDraft, id } : p)) : [...prev, { ...playerDraft, id }];
    });
    setShowPlayerForm(false);
    setEditingPlayer(null);
  }

  async function deletePlayer(id) {
    const { error } = await supabase.from("players").delete().eq("id", id);
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setPlayers((prev) => prev.filter((p) => p.id !== id));
  }

  function resetNewForm() {
    setNewType("foci");
    setNewTitle("");
    setNewDate(nextWednesdayISO());
    setNewStart("19:30");
    setNewEnd("21:00");
    setNewLocation(LOCATIONS[0]);
    setNewLocationOther("");
    setNewFee(2000);
    setNewCost(LOCATION_COSTS[LOCATIONS[0]] || 0);
  }

  async function createOccasion() {
    const o = {
      id: uid(),
      type: newType,
      title: newType === "esemeny" ? newTitle : "Heti foci",
      date: newDate,
      startTime: newStart,
      endTime: newEnd,
      location: newLocation,
      locationOther: newLocation === "Egyéb" ? newLocationOther : "",
      fee: Number(newFee) || 0,
      cost: Number(newCost) || 0,
      responses: {},
      payments: {},
    };
    const { error } = await supabase.from("occasions").insert(toDbOccasion(o));
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setOccasions((prev) => [...prev, o].sort((a, b) => new Date(b.date) - new Date(a.date)));
    setSelectedId(o.id);
    setShowNewForm(false);
    resetNewForm();
  }

  function setResponse(occId, playerId, value) {
    setOccasions((prev) =>
      prev.map((o) => {
        if (o.id !== occId) return o;
        const responses = { ...(o.responses || {}) };
        const payments = { ...o.payments };
        if (responses[playerId] === value) {
          delete responses[playerId];
          delete payments[playerId];
        } else {
          responses[playerId] = value;
          if (value === "yes") {
            if (payments[playerId] === undefined) payments[playerId] = false;
          } else {
            delete payments[playerId];
          }
        }
        const updated = { ...o, responses, payments };
        persistOccasion(updated);
        return updated;
      })
    );
  }

  function togglePayment(occId, playerId) {
    setOccasions((prev) =>
      prev.map((o) => {
        if (o.id !== occId) return o;
        const updated = { ...o, payments: { ...o.payments, [playerId]: !o.payments[playerId] } };
        persistOccasion(updated);
        return updated;
      })
    );
  }

  function updateOccasionFee(occId, fee) {
    setOccasions((prev) =>
      prev.map((o) => {
        if (o.id !== occId) return o;
        const updated = { ...o, fee: Number(fee) || 0 };
        persistOccasion(updated);
        return updated;
      })
    );
  }

  function updateOccasionCost(occId, cost) {
    setOccasions((prev) =>
      prev.map((o) => {
        if (o.id !== occId) return o;
        const updated = { ...o, cost: Number(cost) || 0 };
        persistOccasion(updated);
        return updated;
      })
    );
  }

  async function deleteOccasion(occId) {
    const { error } = await supabase.from("occasions").delete().eq("id", occId);
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setOccasions((prev) => {
      const next = prev.filter((o) => o.id !== occId);
      setSelectedId(next[0]?.id ?? null);
      return next;
    });
  }

  async function submitExtraFee() {
    if (!extraDraft.label.trim() || !extraDraft.amount) return;
    const targetIds = extraDraft.targetIds.length > 0 ? extraDraft.targetIds : players.map((p) => p.id);
    const payments = {};
    targetIds.forEach((id) => (payments[id] = false));
    const f = { id: uid(), label: extraDraft.label, amount: Number(extraDraft.amount), targetIds, payments };
    const { error } = await supabase.from("extra_fees").insert(toDbExtra(f));
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setExtraFees((prev) => [...prev, f]);
    setExtraDraft({ label: "", amount: "", targetIds: [] });
    setShowExtraForm(false);
  }

  function toggleExtraPayment(feeId, playerId) {
    setExtraFees((prev) =>
      prev.map((f) => {
        if (f.id !== feeId) return f;
        const updated = { ...f, payments: { ...f.payments, [playerId]: !f.payments[playerId] } };
        supabase.from("extra_fees").update(toDbExtra(updated)).eq("id", feeId).then(({ error }) => {
          if (error) {
            console.error(error);
            setStorageError(true);
          }
        });
        return updated;
      })
    );
  }

  async function deleteExtraFee(feeId) {
    const { error } = await supabase.from("extra_fees").delete().eq("id", feeId);
    if (error) {
      console.error(error);
      setStorageError(true);
      return;
    }
    setExtraFees((prev) => prev.filter((f) => f.id !== feeId));
  }

  function playerName(id) {
    return players.find((p) => p.id === id)?.name || "Ismeretlen";
  }

  function debts() {
    const map = {};
    players.forEach((p) => (map[p.id] = 0));
    occasions.forEach((o) => {
      Object.keys(o.responses || {}).forEach((id) => {
        if (o.responses[id] === "yes" && !o.payments[id]) map[id] = (map[id] || 0) + (o.fee || 0);
      });
    });
    extraFees.forEach((f) => {
      f.targetIds.forEach((id) => {
        if (!f.payments[id]) map[id] = (map[id] || 0) + (f.amount || 0);
      });
    });
    return players.map((p) => ({ ...p, debt: map[p.id] || 0 })).filter((p) => p.debt > 0).sort((a, b) => b.debt - a.debt);
  }

  function kassza() {
    const realized = occasions.filter(isOccasionPast);
    const upcoming = occasions.filter((o) => !isOccasionPast(o));
    const feeIncome = realized.reduce(
      (sum, o) => sum + Object.keys(o.responses || {}).filter((id) => o.responses[id] === "yes" && o.payments[id]).length * (o.fee || 0),
      0
    );
    const extraIncome = extraFees.reduce((sum, f) => sum + f.targetIds.filter((id) => f.payments[id]).length * (f.amount || 0), 0);
    const income = feeIncome + extraIncome;
    const expense = realized.reduce((sum, o) => sum + (o.cost || 0), 0);
    const balance = income - expense;
    const outstanding = debts().reduce((sum, p) => sum + p.debt, 0);
    const upcomingCost = upcoming.reduce((sum, o) => sum + (o.cost || 0), 0);
    return { income, expense, balance, outstanding, upcomingCost, projected: balance + outstanding };
  }

  function stats() {
    const pastFoci = occasions.filter((o) => o.type === "foci" && isOccasionPast(o));

    const attendance = players
      .map((p) => ({
        name: p.name,
        count: pastFoci.filter((o) => (o.responses || {})[p.id] === "yes").length,
      }))
      .sort((a, b) => b.count - a.count);

    const locationMap = {};
    pastFoci.forEach((o) => {
      const loc = o.location === "Egyéb" ? o.locationOther || "Egyéb" : o.location;
      locationMap[loc] = (locationMap[loc] || 0) + 1;
    });
    const locationData = Object.entries(locationMap).map(([name, count]) => ({ name, count }));

    const monthMap = {};
    pastFoci.forEach((o) => {
      const d = new Date(o.date);
      const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
      monthMap[key] = (monthMap[key] || 0) + 1;
    });
    const monthlyData = Object.keys(monthMap)
      .sort()
      .map((key) => {
        const [y, m] = key.split("-");
        const label = new Date(Number(y), Number(m) - 1).toLocaleDateString("hu-HU", { month: "short", year: "2-digit" });
        return { name: label, count: monthMap[key] };
      });

    const totalGames = pastFoci.length;
    const totalAttendance = pastFoci.reduce(
      (sum, o) => sum + Object.values(o.responses || {}).filter((v) => v === "yes").length,
      0
    );
    const avgAttendance = totalGames ? totalAttendance / totalGames : 0;

    const KCAL_PER_PERSON_MINUTE = 10; // közepes intenzitású kispályás foci, átlagos felnőtt férfi becslés
    const totalPersonMinutes = pastFoci.reduce((sum, o) => {
      const dur = durationMinutes(o);
      const attendeeCount = Object.values(o.responses || {}).filter((v) => v === "yes").length;
      return sum + dur * attendeeCount;
    }, 0);
    const totalCalories = totalPersonMinutes * KCAL_PER_PERSON_MINUTE;

    return {
      attendance,
      locationData,
      monthlyData,
      totalGames,
      totalAttendance,
      avgAttendance,
      totalPersonMinutes,
      totalCalories,
      topPlayer: attendance[0],
    };
  }

  const selected = occasions.find((o) => o.id === selectedId) || occasions[0];

  if (loading) {
    return (
      <div style={{ background: C.bg, color: C.text }} className="min-h-screen flex items-center justify-center font-sans">
        Betöltés...
      </div>
    );
  }

  return (
    <div style={{ background: C.bg, color: C.text }} className="min-h-screen font-sans pb-24">
      <style>{`
        .font-display { font-family: 'Bebas Neue', sans-serif; letter-spacing: 0.03em; }
        .font-sans { font-family: 'Inter', sans-serif; }
      `}</style>

      <div style={{ borderBottom: `1px solid ${C.line}`, background: C.bgElevated }} className="sticky top-0 z-20 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <img src={LOGO} alt="SVAT SE logó" className="w-9 h-9 rounded-full" style={{ border: `1px solid ${C.line}` }} />
          <div className="leading-none">
            <h1 className="font-display text-2xl leading-none" style={{ color: C.accent }}>ÚJPESTI APÁK</h1>
            <p className="text-[10px] tracking-widest" style={{ color: C.textMuted }}>SVAT SE</p>
          </div>
        </div>
        {isAdmin ? (
          <button onClick={() => setIsAdmin(false)} style={{ background: C.bgCard, color: C.accent }} className="flex items-center gap-1 text-xs font-semibold px-3 py-2 rounded-full">
            <Unlock size={14} /> Admin <LogOut size={14} />
          </button>
        ) : (
          <button onClick={() => setShowAdminModal(true)} style={{ background: C.bgCard, color: C.textMuted }} className="flex items-center gap-1 text-xs font-semibold px-3 py-2 rounded-full">
            <Lock size={14} /> Admin
          </button>
        )}
      </div>

      <div className="px-4 pt-4 max-w-xl mx-auto">
        {storageError && (
          <div style={{ background: "#4A1F1F", border: `1px solid ${C.accent2}`, color: C.accent2 }} className="rounded-lg p-3 text-xs mb-4">
            Egy adatbázis-művelet nem sikerült. Ellenőrizd az internetkapcsolatot, és próbáld újra.
          </div>
        )}
        {tab === "home" && (
          <HomeTab
            occasions={occasions}
            selected={selected}
            setSelectedId={setSelectedId}
            players={players}
            isAdmin={isAdmin}
            setResponse={setResponse}
            togglePayment={togglePayment}
            updateOccasionFee={updateOccasionFee}
            updateOccasionCost={updateOccasionCost}
            deleteOccasion={deleteOccasion}
            showNewForm={showNewForm}
            setShowNewForm={setShowNewForm}
            newType={newType} setNewType={setNewType}
            newTitle={newTitle} setNewTitle={setNewTitle}
            newDate={newDate} setNewDate={setNewDate}
            newStart={newStart} setNewStart={setNewStart}
            newEnd={newEnd} setNewEnd={setNewEnd}
            newLocation={newLocation} setNewLocation={setNewLocation}
            newLocationOther={newLocationOther} setNewLocationOther={setNewLocationOther}
            newFee={newFee} setNewFee={setNewFee}
            newCost={newCost} setNewCost={setNewCost}
            createOccasion={createOccasion}
          />
        )}

        {tab === "players" && <PlayersTab players={players} isAdmin={isAdmin} openPlayerForm={openPlayerForm} deletePlayer={deletePlayer} />}

        {tab === "money" && (
          <MoneyTab
            debts={debts()}
            kassza={kassza()}
            extraFees={extraFees}
            players={players}
            isAdmin={isAdmin}
            playerName={playerName}
            toggleExtraPayment={toggleExtraPayment}
            deleteExtraFee={deleteExtraFee}
            showExtraForm={showExtraForm}
            setShowExtraForm={setShowExtraForm}
            extraDraft={extraDraft}
            setExtraDraft={setExtraDraft}
            submitExtraFee={submitExtraFee}
          />
        )}

        {tab === "stats" && <StatsTab stats={stats()} />}
      </div>

      <div style={{ background: C.bgElevated, borderTop: `1px solid ${C.line}` }} className="fixed bottom-0 left-0 right-0 flex justify-around py-2 z-20">
        <NavBtn icon={<CalendarDays size={20} />} label="Aktuális" active={tab === "home"} onClick={() => setTab("home")} />
        <NavBtn icon={<Users size={20} />} label="Játékosok" active={tab === "players"} onClick={() => setTab("players")} />
        <NavBtn icon={<Wallet size={20} />} label="Fizetések" active={tab === "money"} onClick={() => setTab("money")} />
        <NavBtn icon={<TrendingUp size={20} />} label="Statisztika" active={tab === "stats"} onClick={() => setTab("stats")} />
      </div>

      {showAdminModal && (
        <Modal onClose={() => setShowAdminModal(false)}>
          <h2 className="font-display text-3xl mb-1" style={{ color: C.accent }}>
            {adminPassword ? "ADMIN BELÉPÉS" : "ADMIN JELSZÓ BEÁLLÍTÁSA"}
          </h2>
          <p className="text-sm mb-1" style={{ color: C.textMuted }}>
            {adminPassword ? "Add meg az admin jelszót a kezeléshez." : "Még nincs beállítva admin jelszó — most te hozod létre."}
          </p>
          <p className="text-xs mb-4" style={{ color: C.textMuted }}>Admin fiók: {ADMIN_EMAIL}</p>
          <input
            type="password"
            value={adminInput}
            onChange={(e) => setAdminInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleAdminSubmit()}
            placeholder="Jelszó"
            style={{ background: C.bgCard, border: `1px solid ${C.line}`, color: C.text }}
            className="w-full px-3 py-3 rounded-lg outline-none mb-2"
            autoFocus
          />
          {adminError && <p style={{ color: C.accent2 }} className="text-sm mb-2">{adminError}</p>}
          <button onClick={handleAdminSubmit} style={{ background: C.accent, color: C.bg }} className="w-full py-3 rounded-lg font-semibold mt-2">
            {adminPassword ? "Belépés" : "Jelszó mentése"}
          </button>
        </Modal>
      )}

      {showPlayerForm && (
        <Modal onClose={() => setShowPlayerForm(false)}>
          <h2 className="font-display text-3xl mb-4" style={{ color: C.accent }}>{editingPlayer ? "PROFIL SZERKESZTÉSE" : "ÚJ JÁTÉKOS"}</h2>
          <div className="space-y-3">
            <Field label="Név *">
              <input value={playerDraft.name} onChange={(e) => setPlayerDraft({ ...playerDraft, name: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
            <Field label="Mezszám (opcionális)">
              <input type="number" min="1" max="99" value={playerDraft.jerseyNumber} onChange={(e) => setPlayerDraft({ ...playerDraft, jerseyNumber: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
            <Field label="Fotó URL (opcionális, elhagyható)">
              <input value={playerDraft.photo} onChange={(e) => setPlayerDraft({ ...playerDraft, photo: e.target.value })} placeholder="https://..." style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
            <Field label="E-mail">
              <input value={playerDraft.email} onChange={(e) => setPlayerDraft({ ...playerDraft, email: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
            <Field label="Telefon (opcionális)">
              <input value={playerDraft.phone} onChange={(e) => setPlayerDraft({ ...playerDraft, phone: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
          </div>
          <button onClick={submitPlayer} style={{ background: C.accent, color: C.bg }} className="w-full py-3 rounded-lg font-semibold mt-4">Mentés</button>
        </Modal>
      )}
    </div>
  );
}

const inputStyle = { background: C.bgCard, border: `1px solid ${C.line}`, color: C.text };

function Field({ label, children }) {
  return (
    <div>
      <label className="text-xs block mb-1" style={{ color: C.textMuted }}>{label}</label>
      {children}
    </div>
  );
}

function NavBtn({ icon, label, active, onClick }) {
  return (
    <button onClick={onClick} className="flex flex-col items-center gap-1 px-4 py-1">
      <span style={{ color: active ? C.accent : C.textMuted }}>{icon}</span>
      <span className="text-[11px] font-medium" style={{ color: active ? C.accent : C.textMuted }}>{label}</span>
    </button>
  );
}

function Modal({ children, onClose }) {
  return (
    <div className="fixed inset-0 z-30 flex items-end sm:items-center justify-center" style={{ background: "rgba(0,0,0,0.6)" }}>
      <div style={{ background: C.bgElevated, border: `1px solid ${C.line}` }} className="w-full sm:max-w-md rounded-t-2xl sm:rounded-2xl p-5 max-h-[85vh] overflow-y-auto">
        <div className="flex justify-end mb-1">
          <button onClick={onClose} style={{ color: C.textMuted }}><X size={20} /></button>
        </div>
        {children}
      </div>
    </div>
  );
}

function Avatar({ player, size = 40 }) {
  if (player.photo) {
    return <img src={player.photo} alt={player.name} style={{ width: size, height: size, objectFit: "cover", border: `1px solid ${C.line}` }} className="rounded-full" />;
  }
  const initials = player.name.split(" ").map((s) => s[0]).slice(0, 2).join("").toUpperCase();
  return (
    <div style={{ width: size, height: size, background: C.bgCard, color: C.accent }} className="rounded-full flex items-center justify-center font-display text-sm">
      {initials}
    </div>
  );
}

function HomeTab(props) {
  const {
    occasions, selected, setSelectedId, players, isAdmin,
    setResponse, togglePayment, updateOccasionFee, updateOccasionCost, deleteOccasion,
    showNewForm, setShowNewForm,
    newType, setNewType, newTitle, setNewTitle, newDate, setNewDate,
    newStart, setNewStart, newEnd, setNewEnd,
    newLocation, setNewLocation, newLocationOther, setNewLocationOther,
    newFee, setNewFee, newCost, setNewCost, createOccasion,
  } = props;

  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <h2 className="font-display text-3xl">ALKALMAK</h2>
        {isAdmin && (
          <button onClick={() => setShowNewForm(!showNewForm)} style={{ background: C.accent, color: C.bg }} className="flex items-center gap-1 text-sm font-semibold px-3 py-2 rounded-full">
            <Plus size={16} /> Új
          </button>
        )}
      </div>

      {showNewForm && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-4 space-y-3">
          <div className="flex gap-2">
            <button onClick={() => setNewType("foci")} style={{ background: newType === "foci" ? C.accent : "transparent", color: newType === "foci" ? C.bg : C.textMuted, border: `1px solid ${C.line}` }} className="flex-1 py-2 rounded-lg text-sm font-semibold">Heti foci</button>
            <button onClick={() => setNewType("esemeny")} style={{ background: newType === "esemeny" ? C.accent : "transparent", color: newType === "esemeny" ? C.bg : C.textMuted, border: `1px solid ${C.line}` }} className="flex-1 py-2 rounded-lg text-sm font-semibold">Egyedi esemény</button>
          </div>

          {newType === "esemeny" && (
            <Field label="Esemény neve">
              <input value={newTitle} onChange={(e) => setNewTitle(e.target.value)} placeholder="pl. Családi nap" style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
          )}

          <Field label="Dátum">
            <input type="date" value={newDate} onChange={(e) => setNewDate(e.target.value)} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          </Field>

          <div className="flex gap-2">
            <Field label="Kezdés">
              <input type="time" value={newStart} onChange={(e) => setNewStart(e.target.value)} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
            <Field label="Vége">
              <input type="time" value={newEnd} onChange={(e) => setNewEnd(e.target.value)} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
            </Field>
          </div>

          <Field label="Helyszín">
            <select value={newLocation} onChange={(e) => { const loc = e.target.value; setNewLocation(loc); setNewCost(LOCATION_COSTS[loc] ?? 0); }} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none">
              {LOCATIONS.map((l) => <option key={l} value={l}>{l}</option>)}
              <option value="Egyéb">Egyéb (megadom)</option>
            </select>
          </Field>
          {newLocation === "Egyéb" && (
            <input value={newLocationOther} onChange={(e) => setNewLocationOther(e.target.value)} placeholder="Helyszín neve" style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          )}

          <Field label="Díj (Ft, csak ha jön valaki)">
            <input type="number" value={newFee} onChange={(e) => setNewFee(e.target.value)} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          </Field>

          <Field label="Pályabérlés díja (Ft, csapat költsége)">
            <input type="number" value={newCost} onChange={(e) => setNewCost(e.target.value)} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          </Field>

          <button onClick={createOccasion} style={{ background: C.accent, color: C.bg }} className="w-full py-2 rounded-lg font-semibold">Létrehozás</button>
        </div>
      )}

      {occasions.length === 0 && (
        <p style={{ color: C.textMuted }} className="text-sm">Még nincs rögzített alkalom.{isAdmin ? " Hozz létre egyet a fenti gombbal!" : " Az admin fogja kiírni a következőt."}</p>
      )}

      {occasions.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-2 mb-4">
          {occasions.map((o) => (
            <button key={o.id} onClick={() => setSelectedId(o.id)} style={{ background: selected?.id === o.id ? C.accent : C.bgCard, color: selected?.id === o.id ? C.bg : C.text, border: `1px solid ${C.line}` }} className="px-3 py-2 rounded-full text-xs font-semibold whitespace-nowrap capitalize">
              {o.type === "esemeny" ? `🎉 ${fmtDate(o.date)}` : fmtDate(o.date)}
            </button>
          ))}
        </div>
      )}

      {selected && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4">
          <div className="flex items-start justify-between mb-1">
            <div>
              <span className="font-display text-2xl capitalize block">{selected.type === "esemeny" ? selected.title : "Heti foci"}</span>
              <span className="text-xs" style={{ color: C.textMuted }}>{fmtDate(selected.date)} · {selected.startTime}–{selected.endTime}</span>
              <div className="flex items-center gap-1 text-xs mt-1" style={{ color: C.textMuted }}>
                <MapPin size={12} />
                {selected.location === "Egyéb" ? selected.locationOther : selected.location}
              </div>
            </div>
            {isAdmin ? (
              <div className="flex flex-col items-end gap-1">
                <div className="flex items-center gap-2">
                  <span className="text-[10px]" style={{ color: C.textMuted }}>Díj</span>
                  <input type="number" value={selected.fee} onChange={(e) => updateOccasionFee(selected.id, e.target.value)} style={{ ...inputStyle, width: 80 }} className="px-2 py-1 rounded-lg outline-none text-sm" />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[10px]" style={{ color: C.textMuted }}>Bérlés</span>
                  <input type="number" value={selected.cost || 0} onChange={(e) => updateOccasionCost(selected.id, e.target.value)} style={{ ...inputStyle, width: 80 }} className="px-2 py-1 rounded-lg outline-none text-sm" />
                  <button onClick={() => deleteOccasion(selected.id)} style={{ color: C.accent2 }}><Trash2 size={16} /></button>
                </div>
              </div>
            ) : (
              <div className="text-right">
                <span className="font-semibold block" style={{ color: C.accent }}>{fmtHUF(selected.fee)}</span>
                <span className="text-[11px]" style={{ color: C.textMuted }}>Pálya: {fmtHUF(selected.cost || 0)}</span>
              </div>
            )}
          </div>

          {isAdmin && (
            <a href={buildMailto(selected, players)} style={{ background: C.bgElevated, color: C.accent, border: `1px solid ${C.line}` }} className="mt-2 mb-3 flex items-center justify-center gap-2 text-xs font-semibold px-3 py-2 rounded-lg">
              <Mail size={14} /> Értesítés küldése emailben
            </a>
          )}

          {isOccasionPast(selected) && !isAdmin && (
            <p className="text-xs mb-2" style={{ color: C.textMuted }}>Ez az alkalom már lezárult, a jelentkezés innentől nem módosítható.</p>
          )}

          <div className="space-y-2 mt-3">
            {players.length === 0 && <p style={{ color: C.textMuted }} className="text-sm">Adj hozzá játékosokat a Játékosok fülön.</p>}
            {players.map((p) => {
              const response = (selected.responses || {})[p.id];
              const attending = response === "yes";
              const paid = selected.payments[p.id];
              const locked = isOccasionPast(selected) && !isAdmin;
              return (
                <div key={p.id} className="flex items-center justify-between py-1.5" style={{ borderBottom: `1px solid ${C.lineSoft}` }}>
                  <div className="flex items-center gap-2">
                    <Avatar player={p} size={32} />
                    <span className="text-sm">{p.name}{p.jerseyNumber ? ` #${p.jerseyNumber}` : ""}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    {attending && isAdmin && (
                      <button onClick={() => togglePayment(selected.id, p.id)} style={{ background: paid ? "#2D8A5F" : "transparent", border: `1px solid ${paid ? "#2D8A5F" : C.line}`, color: paid ? "#fff" : C.textMuted }} className="text-[11px] px-2 py-1 rounded-full font-semibold">
                        {paid ? "Fizetve" : "Nem fizetett"}
                      </button>
                    )}
                    {attending && !isAdmin && paid !== undefined && (
                      <span style={{ color: paid ? "#5FCB94" : C.accent2 }} className="text-[11px] font-semibold">{paid ? "Fizetve" : "Nem fizetett"}</span>
                    )}
                    <div className="flex gap-1">
                      <button onClick={() => !locked && setResponse(selected.id, p.id, "yes")} disabled={locked} style={{ background: response === "yes" ? C.accent : "transparent", border: `1px solid ${response === "yes" ? C.accent : C.line}`, color: response === "yes" ? C.bg : C.textMuted, opacity: locked ? 0.5 : 1, cursor: locked ? "not-allowed" : "pointer" }} className="text-[11px] font-semibold px-2.5 py-1.5 rounded-full">Igen</button>
                      <button onClick={() => !locked && setResponse(selected.id, p.id, "no")} disabled={locked} style={{ background: response === "no" ? C.accent2 : "transparent", border: `1px solid ${response === "no" ? C.accent2 : C.line}`, color: response === "no" ? "#fff" : C.textMuted, opacity: locked ? 0.5 : 1, cursor: locked ? "not-allowed" : "pointer" }} className="text-[11px] font-semibold px-2.5 py-1.5 rounded-full">Nem</button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function PlayersTab({ players, isAdmin, openPlayerForm, deletePlayer }) {
  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <h2 className="font-display text-3xl">JÁTÉKOSOK</h2>
        <button onClick={() => openPlayerForm(null)} style={{ background: C.accent, color: C.bg }} className="flex items-center gap-1 text-sm font-semibold px-3 py-2 rounded-full">
          <Plus size={16} /> Új
        </button>
      </div>
      {players.length === 0 && <p style={{ color: C.textMuted }} className="text-sm">Még nincs egy játékos sem. Add hozzá az elsőt!</p>}
      <div className="space-y-2">
        {players.map((p) => (
          <div key={p.id} style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-3 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Avatar player={p} size={44} />
              <div>
                <p className="font-semibold text-sm flex items-center gap-1.5">
                  {p.name}
                  {p.jerseyNumber && <span style={{ color: C.accent }}>#{p.jerseyNumber}</span>}
                  {p.isAdmin && <span style={{ background: C.accent, color: C.bg }} className="text-[9px] font-bold px-1.5 py-0.5 rounded-full">ADMIN</span>}
                </p>
                {p.email && <p className="text-xs" style={{ color: C.textMuted }}>{p.email}</p>}
                {p.phone && <p className="text-xs" style={{ color: C.textMuted }}>{p.phone}</p>}
              </div>
            </div>
            <div className="flex items-center gap-1">
              <button onClick={() => openPlayerForm(p)} style={{ color: C.textMuted }} className="p-2"><Pencil size={16} /></button>
              {isAdmin && <button onClick={() => deletePlayer(p.id)} style={{ color: C.accent2 }} className="p-2"><Trash2 size={16} /></button>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function MoneyTab(props) {
  const { debts, kassza, extraFees, players, isAdmin, playerName, toggleExtraPayment, deleteExtraFee, showExtraForm, setShowExtraForm, extraDraft, setExtraDraft, submitExtraFee } = props;
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(buildDebtMessage(debts));
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      console.error(e);
    }
  }

  return (
    <div>
      <h2 className="font-display text-3xl mb-3">KASSZA</h2>
      <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-6 space-y-3">
        <div className="flex items-center justify-between">
          <span className="text-sm" style={{ color: C.textMuted }}>Jelenlegi egyenleg</span>
          <span className="font-display text-3xl" style={{ color: kassza.balance >= 0 ? "#5FCB94" : C.accent2 }}>{fmtHUF(kassza.balance)}</span>
        </div>
        <div className="grid grid-cols-2 gap-3 pt-2" style={{ borderTop: `1px solid ${C.lineSoft}` }}>
          <div>
            <p className="text-[11px]" style={{ color: C.textMuted }}>Befolyt eddig</p>
            <p className="font-semibold text-sm" style={{ color: "#5FCB94" }}>{fmtHUF(kassza.income)}</p>
          </div>
          <div>
            <p className="text-[11px]" style={{ color: C.textMuted }}>Pályabérlés (megvalósult)</p>
            <p className="font-semibold text-sm" style={{ color: C.accent2 }}>{fmtHUF(kassza.expense)}</p>
          </div>
          <div>
            <p className="text-[11px]" style={{ color: C.textMuted }}>Kintlévőség (még nem fizették be)</p>
            <p className="font-semibold text-sm" style={{ color: C.accent }}>{fmtHUF(kassza.outstanding)}</p>
          </div>
          <div>
            <p className="text-[11px]" style={{ color: C.textMuted }}>Közelgő pályabérlés</p>
            <p className="font-semibold text-sm">{fmtHUF(kassza.upcomingCost)}</p>
          </div>
        </div>
        <div className="pt-2 flex items-center justify-between" style={{ borderTop: `1px solid ${C.lineSoft}` }}>
          <span className="text-xs" style={{ color: C.textMuted }}>Ha mindenki fizetne, így állnánk:</span>
          <span className="font-semibold text-sm" style={{ color: kassza.projected >= 0 ? "#5FCB94" : C.accent2 }}>{fmtHUF(kassza.projected)}</span>
        </div>
      </div>

      <h2 className="font-display text-3xl mb-3">KINTLÉVŐSÉGEK</h2>
      {isAdmin && (
        <div className="flex gap-2 mb-3">
          <button onClick={handleCopy} style={{ background: C.bgCard, color: copied ? "#5FCB94" : C.text, border: `1px solid ${C.line}` }} className="flex-1 flex items-center justify-center gap-1.5 text-xs font-semibold px-3 py-2 rounded-lg">
            <Copy size={14} /> {copied ? "Másolva!" : "Lista másolása"}
          </button>
          <a href={buildDebtMailto(debts, players)} style={{ background: C.bgCard, color: C.accent, border: `1px solid ${C.line}` }} className="flex-1 flex items-center justify-center gap-1.5 text-xs font-semibold px-3 py-2 rounded-lg">
            <Mail size={14} /> Lista emailben
          </a>
        </div>
      )}
      {debts.length === 0 ? (
        <p style={{ color: C.textMuted }} className="text-sm mb-6">Mindenki rendezte a tartozását. 🎉</p>
      ) : (
        <div className="space-y-2 mb-6">
          {debts.map((p) => (
            <div key={p.id} style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-3 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Avatar player={p} size={32} />
                <span className="text-sm">{p.name}</span>
              </div>
              <span className="font-semibold" style={{ color: C.accent2 }}>{fmtHUF(p.debt)}</span>
            </div>
          ))}
        </div>
      )}

      <div className="flex items-center justify-between mb-3">
        <h2 className="font-display text-3xl">CÉLBEFIZETÉSEK</h2>
        {isAdmin && (
          <button onClick={() => setShowExtraForm(!showExtraForm)} style={{ background: C.accent, color: C.bg }} className="flex items-center gap-1 text-sm font-semibold px-3 py-2 rounded-full">
            <Plus size={16} /> Új
          </button>
        )}
      </div>

      {showExtraForm && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-4 space-y-3">
          <Field label="Megnevezés (pl. labdavásárlás)">
            <input value={extraDraft.label} onChange={(e) => setExtraDraft({ ...extraDraft, label: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          </Field>
          <Field label="Összeg / fő (Ft)">
            <input type="number" value={extraDraft.amount} onChange={(e) => setExtraDraft({ ...extraDraft, amount: e.target.value })} style={inputStyle} className="w-full px-3 py-2 rounded-lg outline-none" />
          </Field>
          <Field label="Kikre vonatkozik? (üresen: mindenki)">
            <div className="flex flex-wrap gap-2 mt-1">
              {players.map((p) => {
                const checked = extraDraft.targetIds.includes(p.id);
                return (
                  <button key={p.id} onClick={() => setExtraDraft({ ...extraDraft, targetIds: checked ? extraDraft.targetIds.filter((id) => id !== p.id) : [...extraDraft.targetIds, p.id] })} style={{ background: checked ? C.accent : "transparent", color: checked ? C.bg : C.textMuted, border: `1px solid ${checked ? C.accent : C.line}` }} className="text-xs px-2 py-1 rounded-full">
                    {p.name}
                  </button>
                );
              })}
            </div>
          </Field>
          <button onClick={submitExtraFee} style={{ background: C.accent, color: C.bg }} className="w-full py-2 rounded-lg font-semibold">Létrehozás</button>
        </div>
      )}

      {extraFees.length === 0 && <p style={{ color: C.textMuted }} className="text-sm">Nincs aktív célbefizetés.</p>}

      <div className="space-y-3">
        {extraFees.map((f) => {
          const paidCount = f.targetIds.filter((id) => f.payments[id]).length;
          return (
            <div key={f.id} style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4">
              <div className="flex items-center justify-between mb-2">
                <div>
                  <p className="font-semibold text-sm">{f.label}</p>
                  <p className="text-xs" style={{ color: C.textMuted }}>{fmtHUF(f.amount)} / fő · {paidCount}/{f.targetIds.length} fizetve</p>
                </div>
                {isAdmin && <button onClick={() => deleteExtraFee(f.id)} style={{ color: C.accent2 }}><Trash2 size={16} /></button>}
              </div>
              <div className="flex flex-wrap gap-2">
                {f.targetIds.map((id) => {
                  const paid = f.payments[id];
                  return (
                    <button key={id} disabled={!isAdmin} onClick={() => isAdmin && toggleExtraPayment(f.id, id)} style={{ background: paid ? "#2D8A5F" : "transparent", border: `1px solid ${paid ? "#2D8A5F" : C.line}`, color: paid ? "#fff" : C.textMuted }} className="text-[11px] px-2 py-1 rounded-full font-semibold">
                      {playerName(id)}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

const PIE_COLORS = ["#FFC857", "#5FCB94", "#EF6461", "#7FB2E5", "#C39BD3", "#F4A261"];

function StatCard({ label, value, sub }) {
  return (
    <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-3">
      <p className="text-[11px]" style={{ color: C.textMuted }}>{label}</p>
      <p className="font-display text-2xl" style={{ color: C.accent }}>{value}</p>
      {sub && <p className="text-[11px]" style={{ color: C.textMuted }}>{sub}</p>}
    </div>
  );
}

function StatsTab({ stats }) {
  const { attendance, locationData, monthlyData, totalGames, totalAttendance, avgAttendance, totalPersonMinutes, totalCalories, topPlayer } = stats;
  const topFive = attendance.filter((a) => a.count > 0).slice(0, 8);
  const totalHours = totalPersonMinutes / 60;

  if (totalGames === 0) {
    return (
      <div>
        <h2 className="font-display text-3xl mb-3">STATISZTIKA</h2>
        <p style={{ color: C.textMuted }} className="text-sm">
          Még nincs lezajlott alkalom, amiből statisztikát tudnánk mutatni. Amint elmúlik az első heti foci
          időpontja, itt megjelennek a kimutatások.
        </p>
      </div>
    );
  }

  return (
    <div>
      <h2 className="font-display text-3xl mb-3">STATISZTIKA</h2>

      {topPlayer && topPlayer.count > 0 && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.accent}` }} className="rounded-xl p-4 mb-4 flex items-center gap-3">
          <div style={{ background: C.accent }} className="w-11 h-11 rounded-full flex items-center justify-center flex-shrink-0">
            <Trophy size={22} color={C.bg} />
          </div>
          <div>
            <p className="text-[11px]" style={{ color: C.textMuted }}>Legaktívabb játékos</p>
            <p className="font-display text-2xl leading-tight" style={{ color: C.accent }}>{topPlayer.name}</p>
            <p className="text-xs" style={{ color: C.textMuted }}>{topPlayer.count} alkalommal volt ott</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 gap-3 mb-4">
        <StatCard label="Lejátszott alkalmak" value={totalGames} />
        <StatCard label="Összes megjelenés" value={totalAttendance} />
        <StatCard label="Átlag részvétel / alkalom" value={avgAttendance.toFixed(1)} sub="fő" />
        <StatCard label="Helyszínek száma" value={locationData.length} />
        <StatCard label="Összesen sportolt idő" value={Math.round(totalHours).toLocaleString("hu-HU")} sub={`óra · ${totalPersonMinutes.toLocaleString("hu-HU")} játékos-perc`} />
        <StatCard label="Elégetett kalória (becslés)" value={Math.round(totalCalories).toLocaleString("hu-HU")} sub="kcal, csapatszinten összesen" />
      </div>
      <p className="text-[11px] mb-4" style={{ color: C.textMuted }}>
        A kalóriaérték egy átlagos felnőtt férfira és közepes intenzitású kispályás focira vonatkozó becslés
        (~10 kcal/perc/fő) — egyéni testsúlytól és intenzitástól függően eltérhet.
      </p>

      {topFive.length > 0 && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-4">
          <p className="text-sm font-semibold mb-3">Legaktívabb játékosok</p>
          <ResponsiveContainer width="100%" height={Math.max(topFive.length * 34, 100)}>
            <BarChart data={topFive} layout="vertical" margin={{ top: 0, right: 20, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.lineSoft} horizontal={false} />
              <XAxis type="number" allowDecimals={false} tick={{ fill: C.textMuted, fontSize: 11 }} axisLine={{ stroke: C.line }} tickLine={false} />
              <YAxis dataKey="name" type="category" width={90} tick={{ fill: C.text, fontSize: 12 }} axisLine={{ stroke: C.line }} tickLine={false} />
              <Tooltip contentStyle={{ background: C.bgElevated, border: `1px solid ${C.line}`, borderRadius: 8, color: C.text }} labelStyle={{ color: C.text }} />
              <Bar dataKey="count" name="Alkalom" fill={C.accent} radius={[0, 6, 6, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {locationData.length > 0 && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-4">
          <p className="text-sm font-semibold mb-3">Helyszínek szerint</p>
          <div className="flex items-center">
            <ResponsiveContainer width="50%" height={160}>
              <PieChart>
                <Pie data={locationData} dataKey="count" nameKey="name" cx="50%" cy="50%" innerRadius={35} outerRadius={65} paddingAngle={2}>
                  {locationData.map((entry, i) => (
                    <Cell key={entry.name} fill={PIE_COLORS[i % PIE_COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ background: C.bgElevated, border: `1px solid ${C.line}`, borderRadius: 8, color: C.text }} />
              </PieChart>
            </ResponsiveContainer>
            <div className="flex-1 space-y-2">
              {locationData.map((entry, i) => (
                <div key={entry.name} className="flex items-center gap-2 text-xs">
                  <span style={{ width: 10, height: 10, background: PIE_COLORS[i % PIE_COLORS.length] }} className="rounded-full inline-block" />
                  <span style={{ color: C.text }}>{entry.name}</span>
                  <span style={{ color: C.textMuted }} className="ml-auto">{entry.count}×</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {monthlyData.length > 1 && (
        <div style={{ background: C.bgCard, border: `1px solid ${C.line}` }} className="rounded-xl p-4 mb-4">
          <p className="text-sm font-semibold mb-3">Alkalmak havi bontásban</p>
          <ResponsiveContainer width="100%" height={160}>
            <BarChart data={monthlyData} margin={{ top: 0, right: 10, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={C.lineSoft} vertical={false} />
              <XAxis dataKey="name" tick={{ fill: C.textMuted, fontSize: 11 }} axisLine={{ stroke: C.line }} tickLine={false} />
              <YAxis allowDecimals={false} tick={{ fill: C.textMuted, fontSize: 11 }} axisLine={{ stroke: C.line }} tickLine={false} />
              <Tooltip contentStyle={{ background: C.bgElevated, border: `1px solid ${C.line}`, borderRadius: 8, color: C.text }} labelStyle={{ color: C.text }} />
              <Bar dataKey="count" name="Alkalom" fill="#5FCB94" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}
